#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 long long countGood(vector<int>& nums,int k){
  unordered_map<int,long long> freq;long long pairs=0,ans=0;int l=0,n=nums.size();
  for(int r=0;r<n;++r){pairs+=freq[nums[r]]++;while(pairs>=k){ans+=n-r;int x=nums[l++];pairs-=--freq[x];}}
  return ans;
 }
};
